CREATE TABLE IF NOT EXISTS agreements_v2(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_number TEXT NOT NULL,title TEXT NOT NULL,contract_type TEXT NOT NULL,owner_user_id UUID NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version INTEGER NOT NULL DEFAULT 1,UNIQUE(workspace_id,contract_number));
CREATE TABLE IF NOT EXISTS contract_template_versions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),template_key TEXT NOT NULL,version INTEGER NOT NULL,variable_schema JSONB NOT NULL,content_hash TEXT NOT NULL,status TEXT NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(workspace_id,template_key,version));
CREATE TABLE IF NOT EXISTS agreement_document_versions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL REFERENCES agreements_v2(id),draft_id UUID NOT NULL,version INTEGER NOT NULL,content_reference TEXT NOT NULL,content_hash TEXT NOT NULL,status TEXT NOT NULL,created_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),supersedes_id UUID REFERENCES agreement_document_versions(id),ai_proposed BOOLEAN NOT NULL DEFAULT false,UNIQUE(draft_id,version));
CREATE TABLE IF NOT EXISTS agreement_drafts(id UUID PRIMARY KEY,workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL REFERENCES agreements_v2(id),template_version_id UUID NOT NULL REFERENCES contract_template_versions(id),current_document_version_id UUID NOT NULL REFERENCES agreement_document_versions(id),status TEXT NOT NULL,variables JSONB NOT NULL DEFAULT '{}',locked_by UUID,created_by UUID NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),version INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS clause_versions_v2(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),clause_key TEXT NOT NULL,version INTEGER NOT NULL,body_hash TEXT NOT NULL,risk TEXT NOT NULL,guidance_reference TEXT NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(workspace_id,clause_key,version));
CREATE TABLE IF NOT EXISTS clause_instances_v2(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),draft_id UUID NOT NULL REFERENCES agreement_drafts(id),clause_version_id UUID REFERENCES clause_versions_v2(id),body_hash TEXT NOT NULL,source TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS clause_deviations_v2(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),instance_id UUID NOT NULL REFERENCES clause_instances_v2(id),baseline_version_id UUID NOT NULL REFERENCES clause_versions_v2(id),risk TEXT NOT NULL,summary TEXT NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS negotiation_rounds(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL REFERENCES agreements_v2(id),round_number INTEGER NOT NULL,submitted_by UUID NOT NULL,document_version_id UUID NOT NULL REFERENCES agreement_document_versions(id),status TEXT NOT NULL,mandatory_open_items JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(contract_id,round_number));
CREATE TABLE IF NOT EXISTS approval_policies_v2(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),version INTEGER NOT NULL,steps JSONB NOT NULL,status TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agreement_approval_requests(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL REFERENCES agreements_v2(id),document_version_id UUID NOT NULL REFERENCES agreement_document_versions(id),document_hash TEXT NOT NULL,policy_id UUID NOT NULL REFERENCES approval_policies_v2(id),requester_id UUID NOT NULL,status TEXT NOT NULL,completed_steps INTEGER NOT NULL DEFAULT 0,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agreement_approval_decisions(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),request_id UUID NOT NULL REFERENCES agreement_approval_requests(id),step INTEGER NOT NULL,approver_id UUID NOT NULL,decision TEXT NOT NULL,conditions JSONB NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now(),UNIQUE(request_id,step));
CREATE TABLE IF NOT EXISTS signature_packages_v2(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),contract_id UUID NOT NULL REFERENCES agreements_v2(id),approval_request_id UUID NOT NULL REFERENCES agreement_approval_requests(id),document_version_id UUID NOT NULL REFERENCES agreement_document_versions(id),document_hash TEXT NOT NULL,signers JSONB NOT NULL,status TEXT NOT NULL,provider_key TEXT NOT NULL,created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS agreement_execution_certificates(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),package_id UUID NOT NULL UNIQUE REFERENCES signature_packages_v2(id),contract_id UUID NOT NULL REFERENCES agreements_v2(id),document_hash TEXT NOT NULL,canonical_hash TEXT NOT NULL,status TEXT NOT NULL,issued_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS agreement_document_hash_idx ON agreement_document_versions(workspace_id,content_hash);CREATE INDEX IF NOT EXISTS agreement_approval_status_idx ON agreement_approval_requests(workspace_id,status);CREATE INDEX IF NOT EXISTS signature_package_status_idx ON signature_packages_v2(workspace_id,status);
ALTER TABLE agreements_v2 ENABLE ROW LEVEL SECURITY;ALTER TABLE contract_template_versions ENABLE ROW LEVEL SECURITY;ALTER TABLE agreement_document_versions ENABLE ROW LEVEL SECURITY;ALTER TABLE agreement_drafts ENABLE ROW LEVEL SECURITY;ALTER TABLE clause_versions_v2 ENABLE ROW LEVEL SECURITY;ALTER TABLE clause_instances_v2 ENABLE ROW LEVEL SECURITY;ALTER TABLE clause_deviations_v2 ENABLE ROW LEVEL SECURITY;ALTER TABLE negotiation_rounds ENABLE ROW LEVEL SECURITY;ALTER TABLE approval_policies_v2 ENABLE ROW LEVEL SECURITY;ALTER TABLE agreement_approval_requests ENABLE ROW LEVEL SECURITY;ALTER TABLE agreement_approval_decisions ENABLE ROW LEVEL SECURITY;ALTER TABLE signature_packages_v2 ENABLE ROW LEVEL SECURITY;ALTER TABLE agreement_execution_certificates ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['agreements_v2','contract_template_versions','agreement_document_versions','agreement_drafts','clause_versions_v2','clause_instances_v2','clause_deviations_v2','negotiation_rounds','approval_policies_v2','agreement_approval_requests','agreement_approval_decisions','signature_packages_v2','agreement_execution_certificates'] LOOP BEGIN EXECUTE format('CREATE POLICY %I ON %I USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id))',t||'_workspace',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
DO $$ DECLARE t TEXT; BEGIN FOREACH t IN ARRAY ARRAY['agreement_document_versions','negotiation_rounds','agreement_approval_decisions','agreement_execution_certificates'] LOOP BEGIN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation()',t||'_append_only',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
